DROP TABLE IF EXISTS `doctor`;
CREATE TABLE `doctor` (
  `doctorID` int(11) NOT NULL AUTO_INCREMENT COMMENT '医生编号',
  `hospitalID` int(11) NOT NULL COMMENT '所属医院编号',
  `departmentID` int(11) NOT NULL COMMENT '所属科室编号',
  `doctorName` varchar(20) NOT NULL COMMENT '姓名',
  `title` varchar(20) NOT NULL COMMENT '职称',
