  `price` int(11) NOT NULL COMMENT '金额',
  `state` varchar(20) NOT NULL COMMENT '订单状态',
  PRIMARY KEY (`ordersID`) USING BTREE,
  KEY `userID` (`user`) USING BTREE,
  KEY `doctorID` (`doctorID`) USING BTREE,
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`user`) REFERENCES `user` (`user`),
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`doctorID`) REFERENCES `doctor` (`doctorID`)
